#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so GC sees the reference; a raw UObject* is purged by GC (crash in shipping log).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw UArenaScoreTracker* without UPROPERTY, so the garbage collector does not see the reference and purges the object (LogGarbage at 21:05:13); the next OnGoalScored calls AddPoints on the dangling pointer -> EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints. Fix: UPROPERTY() TObjectPtr<UArenaScoreTracker>.",
  "no_colors_cause": "DA_Primary (/Game/Data/Palettes/DA_Primary) is only referenced by a string path in LoadObject, so the cooker never finds a hard reference and does not cook it (bCookAll=False, only /Game/Maps/Arena and /Game/Data/Effects cooked). In the packaged build the load fails (LogStreaming: Couldn't find file for package) and the HUD falls back to gray. Fix: add /Game/Data/Palettes to DirectoriesToAlwaysCook in Config/DefaultGame.ini."
}
